export const CASES = C;
export const PRE = "const P = d => { const o = {}; for (const s of String(d || '').split(' · ')) { const i = s.indexOf(': '); if (i > 0) o[s.slice(0, i)] = s.slice(i + 2); } return o; }; const R = map.nodes.filter(n => (n.detail || '').includes(': ') && (n.detail || '').includes(' · ')).map(n => ({ _id: n.id, _label: n.label, _parent: n.parent, ...P(n.detail) }));\n";
export function mapData(g) { const nodes = g.nodes.map(n => ({ id: n.id, label: n.label, detail: n.detail || '', plane: n.plane, g: n.g, parent: n.parent || null, tags: n.tags || [] })), edges = g.edges.map(e => ({ a: e.a, b: e.b, kind: e.kind, relation: e.relation || '', weight: e.weight ?? 0.5 })), m = { seed: g.seed, nodes, edges }; m.R = new Function('map', PRE + 'return R;')(m); return m; }
export function analyse(c, g) { const m = mapData(g); return String(new Function('map', PRE + 'return (() => {' + c.an + '})();')(m)); }
export function expectation(c, g) { return typeof c.expect === 'function' ? c.expect(mapData(g)) : c.expect; }
export function meets(text, ex) {
  if (ex == null) return true; text = String(text || '');
  if (ex instanceof RegExp) return ex.test(text);
  if (Array.isArray(ex)) return ex.every(x => meets(text, x));
  if (typeof ex === 'string') return text.toLowerCase().includes(ex.toLowerCase());
  if (ex.num != null) { const nums = [...text.replace(/,(?=\d{3})/g, '').matchAll(/\$?(-?\d+(?:\.\d+)?)\s*(billion|million|thousand|[BMk])?\b/gi)].map(m => { const v = +m[1], u = (m[2] || '').toLowerCase(); return u === 'b' || u === 'billion' ? v * 1000 : u === 'k' || u === 'thousand' ? v / 1000 : v; }); return nums.some(v => Math.abs(v - ex.num) <= Math.max(Math.abs(ex.num) * (ex.tol || 0), ex.tol === 0 ? 0.5 : 0)); }
  return false;
}
